import * as T from 'three';import {RoundedBoxGeometry} from './vendor/addons/geometries/RoundedBoxGeometry.js';import {FLOOR,hammerPose} from './course.mjs';
export const colors={cream:0xf4ecda,mint:0x9bc8b7,peach:0xe9a186,teal:0x3c777c,lilac:0xb4a6cc,gold:0xd6bb79,aqua:0x91cbd1};
export function makeArt(scene){const mats={};for(const [name,color] of Object.entries(colors))mats[name]=new T.MeshPhysicalMaterial({color,roughness:.46,metalness:name==='gold'?.5:0,clearcoat:.3,clearcoatRoughness:.4});mats.lamp=new T.MeshStandardMaterial({color:0xffdc9c,emissive:0xffb85b,emissiveIntensity:2.5,roughness:.3});mats.glass=new T.MeshPhysicalMaterial({color:colors.aqua,transparent:true,opacity:.45,roughness:.18,metalness:.1,depthWrite:false,side:T.DoubleSide});mats.dark=new T.MeshStandardMaterial({color:0x30545a,roughness:.6});
function mesh(geo,mat,parent=scene){const m=new T.Mesh(geo,mats[mat]||mat);m.castShadow=mat!=='glass';m.receiveShadow=true;parent.add(m);return m;}
function box(size,pos,mat,parent=scene,r=.16){const bevel=Math.min(r,Math.min(...size)*.22);const g=bevel>.015?new RoundedBoxGeometry(...size,2,bevel):new T.BoxGeometry(...size);const m=mesh(g,mat,parent);m.position.set(...pos);return m;}
function sphere(r,pos,mat,parent=scene,scale=[1,1,1]){const m=mesh(new T.SphereGeometry(r,24,16),mat,parent);m.position.set(...pos);m.scale.set(...scale);return m;}
function cylinder(r,h,pos,mat,parent=scene,rTop=r){const m=mesh(new T.CylinderGeometry(rTop,r,h,24),mat,parent);m.position.set(...pos);return m;}
function beam(a,b,r,mat,parent=scene){const A=new T.Vector3(...a),B=new T.Vector3(...b),mid=A.clone().add(B).multiplyScalar(.5);const m=mesh(new T.CylinderGeometry(r,r,A.distanceTo(B),12),mat,parent);m.position.copy(mid);m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),B.sub(A).normalize());return m;}
function textSign(text,w,h,pos,parent=scene,mat='teal'){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=128;const c=canvas.getContext('2d');c.fillStyle='#356e71';c.fillRect(0,0,512,128);c.fillStyle='#fff4d9';c.textAlign='center';c.textBaseline='middle';c.font='600 62px system-ui';c.fillText(text,256,67);const tex=new T.CanvasTexture(canvas);tex.colorSpace=T.SRGBColorSpace;const material=new T.MeshStandardMaterial({map:tex,roughness:.5});const board=box([w,h,.4],pos,'cream',parent);const label=mesh(new T.PlaneGeometry(w*.94,h*.8),material,parent);label.position.set(pos[0],pos[1],pos[2]-.211);label.rotation.y=Math.PI;label.userData.textSign=true;label.material.side=T.DoubleSide;return board;}
function lamp(x,z,y=2.8,parent=scene){cylinder(.12,y,[x,y/2,z],'gold',parent);sphere(.34,[x,y+.08,z],'lamp',parent);cylinder(.42,.14,[x,y-.22,z],'cream',parent);}
function tree(x,z,s=1,parent=scene){cylinder(.18,1.6*s,[x,.8*s,z],'gold',parent);sphere(1.2*s,[x,2.25*s,z],'mint',parent,[.8,1.1,.8]);sphere(.85*s,[x+.5*s,2.6*s,z+.2*s],'mint',parent);box([1.7*s,.5,1.7*s],[x,.25,z],'cream',parent);}
function building(x,z,w=4,h=4,roof='mint',parent=scene){const group=new T.Group();group.position.set(x,0,z);parent.add(group);box([w,h,w*.72],[0,h/2,0],'cream',group);cylinder(w*.55,.32,[0,h+.08,0],roof,group);sphere(w*.5,[0,h+.16,0],roof,group,[1,.55,.8]);for(const side of [-1,1])for(let k=0;k<3;k++){box([w*.18,h*.42,.05],[(k-1)*w*.28,h*.48,side*w*.363],'lamp',group);box([w*.23,.12,.12],[(k-1)*w*.28,h*.25,side*w*.37],'gold',group);}cylinder(w*.12,.4,[0,h+w*.25,0],'gold',group);return group;}
function robot(x,z,parent=scene,s=1){const g=new T.Group();g.position.set(x,0,z);g.scale.setScalar(s);parent.add(g);box([.9,1.1,.65],[0,1,0],'cream',g);sphere(.56,[0,1.9,0],'mint',g,[1,.85,.9]);box([.75,.27,.08],[0,1.94,-.46],'dark',g);sphere(.06,[-.17,1.96,-.51],'lamp',g);sphere(.06,[.17,1.96,-.51],'lamp',g);for(const side of [-1,1]){box([.29,.4,.6],[side*.28,.25,0],'teal',g);beam([side*.55,1.35,0],[side*.68,.8,0],.13,'peach',g);}return g;}
function saturn(x,z,y=9){const g=new T.Group();g.position.set(x,y,z);scene.add(g);sphere(3.2,[0,0,0],'peach',g,[1,.88,1]);const ring=mesh(new T.TorusGeometry(4.7,.18,12,80),'gold',g);ring.rotation.x=Math.PI*.4;ring.rotation.z=.18;const glow=mesh(new T.TorusGeometry(4.5,.06,8,80),'lamp',g);glow.rotation.copy(ring.rotation);cylinder(.35,y,[x,y/2,z],'gold');return g;}
function ferris(x,z){const g=new T.Group();g.position.set(x,0,z);scene.add(g);beam([-3,0,0],[0,8,0],.28,'mint',g);beam([3,0,0],[0,8,0],.28,'mint',g);const wheel=new T.Group();wheel.position.y=8;g.add(wheel);for(const depth of [-.4,.4]){const m=mesh(new T.TorusGeometry(5,.12,10,64),'gold',wheel);m.position.z=depth;}for(let i=0;i<10;i++){const a=i/10*Math.PI*2,px=Math.cos(a)*5,py=Math.sin(a)*5;beam([0,0,0],[px,py,0],.06,'cream',wheel);const seat=box([1.15,.85,1.1],[px,py,0],i%2?'peach':'mint',wheel);sphere(.58,[px,py+.5,0],'glass',wheel,[1,.55,1]);}return wheel;}
function woodTexture(){const cv=document.createElement('canvas');cv.width=cv.height=512;const c=cv.getContext('2d');c.fillStyle='#806047';c.fillRect(0,0,512,512);for(let i=0;i<550;i++){const yy=(i*71.23)%512;c.strokeStyle=`rgba(${i%2?200:45},${i%2?157:29},${i%2?109:18},.08)`;c.lineWidth=1+(i%4)*.3;c.beginPath();for(let x=0;x<=512;x+=8)c.lineTo(x,yy+2*Math.sin(x/45+i)*Math.sin(i));c.stroke();}const t=new T.CanvasTexture(cv);t.wrapS=t.wrapT=T.RepeatWrapping;t.repeat.set(5,4);t.colorSpace=T.SRGBColorSpace;return t;}
const tableMat=new T.MeshStandardMaterial({map:woodTexture(),roughness:.68,color:0xd5bb94});box([250,5,210],[0,-7,0],tableMat);box([143,4.8,97],[1,-2.7,2],'mint');box([142,1,96],[1,.15,2],'cream');
for(let x=-65;x<70;x+=7)for(const z of [-43,46]){box([5,.055,4.3],[x,.68,z],((x+65)/7)%2?'cream':'mint');if(Math.abs(x%14)<5)lamp(x,z,.9);}
for(const x of [-40,0,44])for(const z of [-18,-5,8,20]){building(x+7,z,2.5,3.5,z%2?'mint':'peach');}
const wheel=ferris(-62,11),planet=saturn(58,-25,10);
for(const [x,z,w,h,roof] of [[-58,-32,5,5,'peach'],[-24,35,7,5,'mint'],[-8,36,4,7,'lilac'],[14,36,6,5,'peach'],[35,39,5,6,'mint'],[61,31,5,7,'mint'],[-56,33,5,3,'lilac']])building(x,z,w,h,roof);
// A miniature soda café with a striped awning, small tables and transparent rooftop dome.
textSign('SODA',4,1.0,[-24,5.25,32.3]);for(let i=0;i<7;i++)box([1,.16,2.2],[-27+i,3.3,30.9],i%2?'cream':'peach');sphere(2.8,[14,6.5,36],'glass',scene,[1,.65,1]);sphere(.22,[14,8.3,36],'gold');
for(const [x,z] of [[-31,34],[-18,32],[22,34],[54,37]]){cylinder(1.2,.18,[x,1.7,z],'cream');cylinder(.13,1.6,[x,.8,z],'gold');for(const side of [-1,1])cylinder(.45,.5,[x+side*1.8,.8,z],'mint');}
for(const [x,z] of [[-53,-13],[-54,25],[-22,-32],[20,-31],[63,12],[66,-9],[-33,36],[7,39],[40,36]])tree(x,z,.85);
for(let i=0;i<18;i++){const x=-57+i*7;lamp(x,-37,2.5);if(i%2===0)lamp(x,39,2.3);}
robot(-21,31,scene,.9);robot(57,26,scene,1.15);robot(-54,-29,scene,.8);
for(const [x,z] of [[-26,-32],[24,-31]]){const rocket=new T.Group();rocket.position.set(x,0,z);scene.add(rocket);cylinder(.9,3.2,[0,2.2,0],'cream',rocket);const tip=mesh(new T.ConeGeometry(.9,1.9,24),'peach',rocket);tip.position.set(0,4.75,0);sphere(.5,[0,2.7,-.7],'glass',rocket);for(const side of [-1,1])box([.5,1.4,1.1],[side,1,0],'mint',rocket);}
return {mats,mesh,box,sphere,cylinder,beam,lamp,textSign,animate(t){wheel.rotation.z=t*.045;planet.rotation.y=Math.sin(t*.08)*.15;}};}
export function buildTrackArt(course,x,art,parent){const {mesh,box,sphere,cylinder,beam,mats,textSign}=art;const root=new T.Group();root.position.x=x;root.scale.x=-1;parent.add(root);const bumpers=[],hammers=[];
function geometry(triangles){const p=[];for(const tri of triangles)for(const v of tri)p.push(...v);const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(p,3));geo.computeVertexNormals();return geo;}
for(const road of course.roads){const g=geometry(road.top);const top=mesh(g,road.loop?'aqua':'cream',root);top.material.side=T.DoubleSide;const skirt=mesh(g.clone(),'mint',root);skirt.position.y=-.48;skirt.material.side=T.DoubleSide;const rail=mesh(geometry(road.rails),road.loop?'glass':'mint',root);rail.material.side=T.DoubleSide;
 const sides=[];for(let i=0;i<road.samples.length-1;i++){const a=road.samples[i],b=road.samples[i+1];for(const side of [-1,1]){const A=a.p.map((v,k)=>v+a.right[k]*side*a.width/2),B=b.p.map((v,k)=>v+b.right[k]*side*b.width/2),AA=A.map((v,k)=>v-a.up[k]*.48),BB=B.map((v,k)=>v-b.up[k]*.48);sides.push([A,AA,B],[B,AA,BB]);}}const shell=mesh(geometry(sides),'cream',root);shell.material.side=T.DoubleSide;
 for(let i=0;i<road.samples.length;i+=Math.max(8,Math.round(road.samples.length/5))){const s=road.samples[i];if(s.p[1]>3.8&&s.up[1]<.45)continue;const top=s.p[1]-.5;if(top>.8){cylinder(.22,top-.6,[s.p[0],(top+.6)/2,s.p[2]],'gold',root);box([.9,.25,.9],[s.p[0],.7,s.p[2]],'peach',root);}}
}
for(const b of course.bumpers){const g=new T.Group();g.position.set(...b.center);root.add(g);const core=mesh(new T.CapsuleGeometry(b.radius,b.half*2,8,16),'peach',g);core.rotation.z=Math.PI/2;sphere(.38,[0,.74,0],'gold',g,[1,.2,1]);bumpers.push({group:g,fallback:[core,...g.children.filter(c=>c!==core)],spec:b});}
for(const h of course.hammers){const z=h.pivot[2];for(const side of [-1,1]){cylinder(.23,7.2,[side*(course.width/2+.55),FLOOR+3.6,z],'cream',root);box([1.1,.7,1.1],[side*(course.width/2+.55),FLOOR+.1,z],'peach',root);}beam([-course.width/2-.55,h.pivot[1],z],[course.width/2+.55,h.pivot[1],z],.23,'mint',root);sphere(.45,h.pivot,'gold',root);const swing=new T.Group();swing.position.set(...h.pivot);root.add(swing);beam([0,0,0],[0,-h.length,0],.12,'gold',swing);const head=new T.Group();head.position.y=-h.length;swing.add(head);const fallback=sphere(h.radius,[0,0,0],'peach',head,[1.05,.83,.82]);const ring=mesh(new T.TorusGeometry(h.radius*.9,.1,10,32),'gold',head);ring.rotation.y=Math.PI/2;hammers.push({swing,head,fallback:[fallback,ring],spec:h});}
for(const b of course.boosts){for(let z=b.z0;z<b.z1;z+=1.1){const stripe=box([b.half*1.5,.025,.22],[b.x,FLOOR+.018,z],'gold',root);stripe.rotation.y=.18;}}
for(const z of [course.start[2]-1,course.finishZ+1]){for(const side of [-1,1]){cylinder(.2,4.3,[side*(course.width/2+.6),FLOOR+2.1,z],'cream',root);sphere(.4,[side*(course.width/2+.6),FLOOR+4.5,z],'lamp',root);}textSign(z<0?'START':'FINISH',course.width*.7,1.4,[0,FLOOR+4,z],root);}
for(let i=0;i<Math.floor(course.width);i++)for(let k=0;k<2;k++)box([1,.025,.6],[-course.width/2+.5+i,FLOOR+.02,course.finishZ-1+k*.6],(i+k)%2?'teal':'cream',root);
root.traverse(o=>{if(o.userData.textSign)o.scale.x=-1;});
return {root,bumpers,hammers,update(time){for(const h of hammers)h.swing.rotation.z=hammerPose(h.spec,time).angle;},dispose(){root.traverse(o=>{if(o.geometry&&!o.userData.sharedProp)o.geometry.dispose();});parent.remove(root);}};}
